# Diagnostic only: observe existing host dispatch counters without changing dispatch.
import atexit, json, os, sys, threading, time
from pathlib import Path

def dump():
    m = sys.modules.get('vllm_mach.mxfp6.gdn_decode')
    if m is not None and hasattr(m, 'stats'):
        counters = m.stats()
        if counters:
            Path('/data/lxy/moe_recheck_20260928/default-isolated').mkdir(exist_ok=True)
            Path(f'/data/lxy/moe_recheck_20260928/default-isolated/gdn-stats-{os.getpid()}.json').write_text(json.dumps({'pid':os.getpid(),'epoch':time.time(),'stats':counters},indent=2)+'\n')

def observe():
    while True:
        time.sleep(5)
        try: dump()
        except Exception: pass

atexit.register(dump)
threading.Thread(target=observe,daemon=True).start()
